package model

// IgnManifest records files created by ign so they can be removed later.
type IgnManifest struct {
	// Version is the project metadata schema version. Missing means version 1.
	Version int `json:"version,omitempty"`
	// OutputRoot is the project output root for version 2 metadata.
	OutputRoot string `json:"output_root,omitempty"`
	// Files contains generated file paths as written during checkout/update.
	Files []string `json:"files,omitempty"`
	// Templates contains per-template generated file ownership for version 2 metadata.
	Templates []IgnManifestTemplateRecord `json:"templates,omitempty"`
}

// IgnManifestTemplateRecord records files generated by one template checkout.
type IgnManifestTemplateRecord struct {
	// ID references a TemplateCheckoutRecord.
	ID string `json:"id"`
	// Order is the monotonic checkout order.
	Order int `json:"order"`
	// Files contains generated file paths as written during checkout/update.
	Files []string `json:"files"`
}
